		@Parameter(name = "content", description = "약관 내용", example = "[필수] 개인정보 수집 및 이용 동의", required = true, schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "/agree", method = RequestMethod.POST) 
	public String createWebTerms(@RequestParamMap(requiredValues= {"title", "version", "content"}) ParamMap param, Model model, HttpSession session) throws LogicException {
		model.addAllAttributes(mngTermsService.createMngAgreeTerms(param));
		return JSON_VIEW;
	}
