180	    /**
181	     * 서버의 가입자 등록 API를 통해 가입자를 등록하고, DB에서 암호화된 CTN을 반환한다.
182	     * SecurityModule 의존 테스트의 setup 데이터 준비에 사용.
183	     *
184	     * @param baseUrl 서버 URL
185	     * @param sessionId JOIN 관리자(AUTHZ=05) 세션 ID
186	     * @param ctn 평문 전화번호 (예: "01012345678")
187	     * @param corporationYn "1"(법인) 또는 "0"(개인)
188	     * @param managerName 관리자명
189	     * @param conn DB 연결
190	     * @return 서버가 암호화한 CTN 값
191	     */
192	    static String createMemberAndGetEncryptedCtn(String baseUrl, String sessionId, String ctn,
193	            String corporationYn, String managerName, Connection conn) {
194	        io.restassured.RestAssured.given()
195	            .baseUri(baseUrl)
196	            .cookie("SESSION", sessionId)
197	            .header("X-Requested-With", "XMLHttpRequest")
198	            .contentType("multipart/form-data")
199	            .multiPart("ctn", ctn)
200	            .multiPart("exceptionPolicy", "0")
201	            .multiPart("managerName", managerName)
202	            .multiPart("corporationYn", corporationYn)
203	            .multiPart("immediately", "false")
