205	        .when().post("/web/admin/members/");
206	
207	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
208	                "SELECT CTN FROM MEMBER ORDER BY MEMBER_SEQ DESC LIMIT 1")) {
209	            java.sql.ResultSet rs = ps.executeQuery();
210	            if (rs.next()) {
211	                return rs.getString("CTN");
212	            }
213	            throw new RuntimeException("Member not found after creation: ctn=" + ctn);
214	        } catch (RuntimeException e) {
215	            throw e;
216	        } catch (Exception e) {
217	            throw new RuntimeException("Failed to read encrypted CTN", e);
218	        }
219	    }
