221	    // =========================================================================
222	    // AWS Encryption SDK 기반 CTN 암호화 유틸리티
223	    // =========================================================================
224	
225	    private static com.amazonaws.encryptionsdk.AwsCrypto awsCrypto;
226	    private static com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager cachingCmm;
227	
228	    /**
229	     * AWS Encryption SDK를 사용하여 평문을 암호화한다.
230	     * 서버의 AwsKmsEncryptionService와 동일한 방식 (Envelope Encryption + Base64).
231	     * LocalStack KMS의 cmk-2 (dataEncryptionService용)를 사용한다.
232	     *
233	     * @param plaintext 평문 (예: "01012345678")
234	     * @return Base64 인코딩된 암호문 (서버가 복호화 가능)
235	     */
236	    static synchronized String kmsEncrypt(String plaintext) {
237	        if (plaintext == null || plaintext.isEmpty()) return "";
238	        initKmsIfNeeded();
239	        try {
240	            com.amazonaws.encryptionsdk.CryptoResult<byte[], ?> result =
241	                awsCrypto.encryptData(cachingCmm,
242	                    plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8),
243	                    java.util.Collections.emptyMap());
244	            return java.util.Base64.getEncoder().encodeToString(result.getResult());
245	        } catch (Exception e) {
246	            throw new RuntimeException("KMS encrypt failed for: " + plaintext, e);
247	        }
248	    }
