420	    /**
421	     * setup SQL 실행 후, 지정된 CLIENT의 ECGI를 KMS(CMK-1)로 암호화된 값으로 UPDATE한다.
422	     * 동시에 ECGI_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
423	     *
424	     * @param conn DB 연결
425	     * @param ecgiSeq 대상 ECGI_SEQ
426	     * @param plainEcgi 평문 ECGI (예: "1234567890")
427	     */
428	    static void encryptEcgi(Connection conn, long ecgiSeq, String plainEcgi) {
429	        String encrypted = kmsEncryptLocation(plainEcgi);
430	        String hash = hmacSha256(plainEcgi);
431	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
432	                "UPDATE ECGI SET ECGI = ?, ECGI_HASH = ? WHERE ECGI_SEQ = ?")) {
433	            ps.setString(1, encrypted);
434	            ps.setString(2, hash);
435	            ps.setLong(3, ecgiSeq);
436	            int updated = ps.executeUpdate();
437	            if (updated == 0) {
438	                throw new RuntimeException("ECGI not found: ECGI_SEQ=" + ecgiSeq);
439	            }
440	        } catch (RuntimeException e) {
441	            throw e;
442	        } catch (Exception e) {
443	            throw new RuntimeException("Failed to encrypt ECGI", e);
444	        }
445	    }
446	
447	    /**
448	     * HMAC-SHA256 해시 생성 (서버의 HashUtil.hmacSha256과 동일 로직).
449	     * pepper는 docker-compose.yml의 HASH_PEPPER 환경변수와 동일해야 한다.
450	     */
451	    static String hmacSha256(String plaintext) {
452	        if (plaintext == null || plaintext.isEmpty()) return "";
453	        String pepper = System.getProperty("test.hash.pepper", "test_pepper_value");
454	        try {
455	            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
456	            javax.crypto.spec.SecretKeySpec keySpec = new javax.crypto.spec.SecretKeySpec(
457	                    pepper.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
458	            mac.init(keySpec);
459	            byte[] hash = mac.doFinal(plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8));
460	            StringBuilder sb = new StringBuilder(hash.length * 2);
461	            for (byte b : hash) sb.append(String.format("%02x", b));
462	            return sb.toString();
463	        } catch (Exception e) {
464	            throw new RuntimeException("HMAC-SHA256 failed", e);
465	        }
466	    }
467	}
