package com.ahope.ds.blackbox;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.Statement;

/**
 * JDK 8 호환 테스트 유틸리티
 */
class TestUtil {

    static {
        // POST/PUT 302 redirect는 RestAssured 기본 설정으로 follow되지 않음
        // 각 테스트에서 .redirects().follow(true)를 명시하거나, 302를 기대하도록 설계
    }

    static byte[] readAllBytes(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] data = new byte[4096];
        int bytesRead;
        while ((bytesRead = is.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, bytesRead);
        }
        return buffer.toByteArray();
    }

    static void executeSql(Connection conn, String resourcePath, Class<?> clazz) {
        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(readAllBytes(is), StandardCharsets.UTF_8);
            StringBuilder cleaned = new StringBuilder();
            for (String rawLine : sql.split("\n")) {
                String line = rawLine.trim();
                if (line.startsWith("--") || line.isEmpty()) continue;
                cleaned.append(line).append(" ");
            }
            for (String statement : cleaned.toString().split(";")) {
                String trimmed = statement.trim();
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL execution failed: " + resourcePath, e);
        }
    }

    static String readResource(String resourcePath, Class<?> clazz) {
        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath)) {
            return new String(readAllBytes(is), StandardCharsets.UTF_8);
        } catch (Exception e) {
            throw new RuntimeException("Resource read failed: " + resourcePath, e);
        }
    }

    /**
     * 관리자 로그인 세션을 획득하여 SESSION 쿠키를 반환한다.
     * 1단계: POST /web/login/ajax (id, pw) → accountSeq 반환
     * 2단계: JDBC로 ACCOUNT_SMS에서 인증번호 조회
     * 3단계: POST /web/login/sms (accountSeq, certificationNo) → 세션 생성
     * 3-B단계: 약관 동의가 필요하면 POST /web/login/agreeTerms 호출
     * 4단계: tokenErr="001"이면 POST /web/login/token 호출하여 loginToken 발급
     *
     * @param baseUrl 서버 URL (예: http://localhost:8080)
     * @param id 관리자 ID
     * @param pw 관리자 비밀번호
     * @param conn DB 연결
     * @return SESSION 쿠키 값
     */
    static String adminLogin(String baseUrl, String id, String pw, Connection conn) {
        // 1단계: 로그인 시도 → SMS 인증번호 발송 + accountSeq 반환
        io.restassured.response.Response loginResp = io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("id", id)
            .formParam("pw", pw)
        .when()
            .post("/web/login/ajax");

        String err = loginResp.jsonPath().getString("err");
        if (!"000".equals(err)) {
            throw new RuntimeException("Login step 1 failed: err=" + err);
        }
        long accountSeq = loginResp.jsonPath().getLong("accountSeq");

        // SESSION는 1단계에서 발급됨 — 이후 모든 요청에 이 쿠키 사용
        String jsessionId = loginResp.getCookie("SESSION");
        if (jsessionId == null || jsessionId.isEmpty()) {
            throw new RuntimeException("No SESSION cookie from login/ajax");
        }

        // 2단계: DB에서 인증번호 직접 조회
        String certNo;
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "SELECT CERTIFICATION_NO FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ?")) {
            ps.setLong(1, accountSeq);
            java.sql.ResultSet rs = ps.executeQuery();
            if (!rs.next()) throw new RuntimeException("No SMS info found for accountSeq=" + accountSeq);
            certNo = rs.getString(1);
        } catch (Exception e) {
            throw new RuntimeException("Failed to read SMS certification", e);
        }

        // 3단계: SMS 인증 → 세션 생성
        io.restassured.response.Response smsResp = io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .cookie("SESSION", jsessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("id", id)
            .formParam("pw", pw)
            .formParam("accountSeq", accountSeq)
            .formParam("certificationNo", certNo)
        .when()
            .post("/web/login/sms");

        String smsErr = smsResp.jsonPath().getString("err");
        if (!"000".equals(smsErr)) {
            throw new RuntimeException("Login step 2 (SMS) failed: err=" + smsErr);
        }

        // 3-B단계: 약관 동의가 필요한 경우 (AUTHZ가 01, 07이 아닌 계정)
        String termsJson = smsResp.jsonPath().getString("terms");
        if (termsJson != null) {
            long mngAgreeTermsSeq = smsResp.jsonPath().getLong("terms.latestTerms.mngAgreeTermsSeq");
            int version = smsResp.jsonPath().getInt("terms.latestTerms.version");

            io.restassured.response.Response agreeResp = io.restassured.RestAssured.given()
                .baseUri(baseUrl)
                .cookie("SESSION", jsessionId)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType("application/x-www-form-urlencoded")
                .formParam("id", id)
                .formParam("pw", pw)
                .formParam("accountSeq", accountSeq)
                .formParam("mngAgreeTermsSeq", mngAgreeTermsSeq)
                .formParam("version", version)
            .when()
                .post("/web/login/agreeTerms");

            String agreeErr = agreeResp.jsonPath().getString("err");
            if (agreeErr != null && !"000".equals(agreeErr)) {
                String agreeErrMsg = agreeResp.jsonPath().getString("errMsg");
                // errMsg가 숫자 코드(100, 200 등)이면 정상 로그인 완료
                if (agreeErrMsg == null || (!agreeErrMsg.matches("\\d+") && !"success".equalsIgnoreCase(agreeErrMsg))) {
                    throw new RuntimeException("Login step 3-B (agreeTerms) failed: err=" + agreeErr + ", errMsg=" + agreeErrMsg);
                }
            }

            // agreeTerms 응답에서 tokenErr 확인
            String tokenErr = agreeResp.jsonPath().getString("tokenErr");
            if ("001".equals(tokenErr)) {
                // 이미 로그인된 세션이 있어 loginToken이 설정되지 않음 → token 발급 요청
                io.restassured.RestAssured.given()
                    .baseUri(baseUrl)
                    .cookie("SESSION", jsessionId)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType("application/x-www-form-urlencoded")
                .when()
                    .post("/web/login/token");
            }
        } else {
            // 약관 동의 불필요 — tokenErr 확인
            String tokenErr = smsResp.jsonPath().getString("tokenErr");
            if ("001".equals(tokenErr)) {
                io.restassured.RestAssured.given()
                    .baseUri(baseUrl)
                    .cookie("SESSION", jsessionId)
                    .header("X-Requested-With", "XMLHttpRequest")
                    .contentType("application/x-www-form-urlencoded")
                .when()
                    .post("/web/login/token");
            }
        }

        return jsessionId;
    }

    /**
     * 서버의 가입자 등록 API를 통해 가입자를 등록하고, DB에서 암호화된 CTN을 반환한다.
     * SecurityModule 의존 테스트의 setup 데이터 준비에 사용.
     *
     * @param baseUrl 서버 URL
     * @param sessionId JOIN 관리자(AUTHZ=05) 세션 ID
     * @param ctn 평문 전화번호 (예: "01012345678")
     * @param corporationYn "1"(법인) 또는 "0"(개인)
     * @param managerName 관리자명
     * @param conn DB 연결
     * @return 서버가 암호화한 CTN 값
     */
    static String createMemberAndGetEncryptedCtn(String baseUrl, String sessionId, String ctn,
            String corporationYn, String managerName, Connection conn) {
        io.restassured.RestAssured.given()
            .baseUri(baseUrl)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("multipart/form-data")
            .multiPart("ctn", ctn)
            .multiPart("exceptionPolicy", "0")
            .multiPart("managerName", managerName)
            .multiPart("corporationYn", corporationYn)
            .multiPart("immediately", "false")
            .multiPart("noteLen", "0")
        .when().post("/web/admin/members/");

        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "SELECT CTN FROM MEMBER ORDER BY MEMBER_SEQ DESC LIMIT 1")) {
            java.sql.ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                return rs.getString("CTN");
            }
            throw new RuntimeException("Member not found after creation: ctn=" + ctn);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to read encrypted CTN", e);
        }
    }

    // =========================================================================
    // AWS Encryption SDK 기반 CTN 암호화 유틸리티
    // =========================================================================

    private static com.amazonaws.encryptionsdk.AwsCrypto awsCrypto;
    private static com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager cachingCmm;

    /**
     * AWS Encryption SDK를 사용하여 평문을 암호화한다.
     * 서버의 AwsKmsEncryptionService와 동일한 방식 (Envelope Encryption + Base64).
     * LocalStack KMS의 cmk-2 (dataEncryptionService용)를 사용한다.
     *
     * @param plaintext 평문 (예: "01012345678")
     * @return Base64 인코딩된 암호문 (서버가 복호화 가능)
     */
    static synchronized String kmsEncrypt(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) return "";
        initKmsIfNeeded();
        try {
            com.amazonaws.encryptionsdk.CryptoResult<byte[], ?> result =
                awsCrypto.encryptData(cachingCmm,
                    plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                    java.util.Collections.emptyMap());
            return java.util.Base64.getEncoder().encodeToString(result.getResult());
        } catch (Exception e) {
            throw new RuntimeException("KMS encrypt failed for: " + plaintext, e);
        }
    }

    @SuppressWarnings("deprecation")
    private static void initKmsIfNeeded() {
        if (awsCrypto != null) return;

        String endpoint = System.getProperty("test.localstack.endpoint", "http://localhost:4566");
        String region = System.getProperty("test.aws.region", "ap-northeast-2");
        String keyAlias = "alias/cmk-2-pltelapne2"; // dataEncryptionService용 CMK

        awsCrypto = com.amazonaws.encryptionsdk.AwsCrypto.builder()
            .withCommitmentPolicy(com.amazonaws.encryptionsdk.CommitmentPolicy.RequireEncryptRequireDecrypt)
            .build();

        software.amazon.awssdk.services.kms.KmsClient kmsClient =
            software.amazon.awssdk.services.kms.KmsClient.builder()
                .region(software.amazon.awssdk.regions.Region.of(region))
                .endpointOverride(java.net.URI.create(endpoint))
                .credentialsProvider(software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(
                    software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test", "test")))
                .build();

        // alias → ARN 변환
        String keyArn = kmsClient.describeKey(
            software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
                .keyId(keyAlias).build()
        ).keyMetadata().arn();

        com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider provider =
            com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider.builder()
                .defaultRegion(software.amazon.awssdk.regions.Region.of(region))
                .customRegionalClientSupplier(r -> kmsClient)
                .buildStrict(keyArn);

        com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache cache =
            new com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache(100);
        cachingCmm = com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager.newBuilder()
            .withMasterKeyProvider(provider)
            .withCache(cache)
            .withMaxAge(5, java.util.concurrent.TimeUnit.MINUTES)
            .withMessageUseLimit(1000)
            .build();
    }

    /**
     * setup SQL 실행 후, 지정된 MEMBER의 CTN을 KMS로 암호화된 값으로 UPDATE한다.
     * 동시에 CTN_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
     *
     * @param conn DB 연결
     * @param memberSeq 대상 MEMBER_SEQ
     * @param plainCtn 평문 CTN (예: "01012345678")
     */
    static void encryptMemberCtn(Connection conn, long memberSeq, String plainCtn) {
        String encrypted = kmsEncrypt(plainCtn);
        String hash = hmacSha256(plainCtn);
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "UPDATE MEMBER SET CTN = ?, CTN_HASH = ? WHERE MEMBER_SEQ = ?")) {
            ps.setString(1, encrypted);
            ps.setString(2, hash);
            ps.setLong(3, memberSeq);
            int updated = ps.executeUpdate();
            if (updated == 0) {
                throw new RuntimeException("MEMBER not found: MEMBER_SEQ=" + memberSeq);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to encrypt MEMBER CTN", e);
        }
    }

    /**
     * setup SQL 실행 후, 지정된 ACCOUNT의 PHONE 컬럼을 KMS로 암호화된 값으로 UPDATE한다.
     * 동시에 PHONE_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
     *
     * AccountService가 phone을 securityModule.AES256_Decrypt로 복호화하므로,
     * setup SQL의 더미값(예: "enc_phone_010")을 실제 KMS 암호화 값으로 치환해야
     * Account 관련 API가 정상 동작한다.
     *
     * @param conn DB 연결
     * @param accountSeq 대상 ACCOUNT_SEQ
     * @param plainPhone 평문 전화번호 (예: "01055599988")
     */
    static void encryptAccountPhone(Connection conn, long accountSeq, String plainPhone) {
        String encrypted = kmsEncrypt(plainPhone);
        String hash = hmacSha256(plainPhone);
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "UPDATE ACCOUNT SET PHONE = ?, PHONE_HASH = ? WHERE ACCOUNT_SEQ = ?")) {
            ps.setString(1, encrypted);
            ps.setString(2, hash);
            ps.setLong(3, accountSeq);
            int updated = ps.executeUpdate();
            if (updated == 0) {
                throw new RuntimeException("ACCOUNT not found: ACCOUNT_SEQ=" + accountSeq);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to encrypt ACCOUNT phone", e);
        }
    }

    // =========================================================================
    // AWS Encryption SDK 기반 ECGI/Location 암호화 유틸리티 (CMK-1)
    // =========================================================================

    private static com.amazonaws.encryptionsdk.AwsCrypto awsCryptoLocation;
    private static com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager cachingCmmLocation;

    /**
     * AWS Encryption SDK를 사용하여 위치 데이터(ECGI 등)를 암호화한다.
     * 서버의 locationEncryptionService (CMK-1)와 동일한 방식.
     *
     * @param plaintext 평문 ECGI (예: "1234567890")
     * @return Base64 인코딩된 암호문
     */
    static synchronized String kmsEncryptLocation(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) return "";
        initKmsLocationIfNeeded();
        try {
            com.amazonaws.encryptionsdk.CryptoResult<byte[], ?> result =
                awsCryptoLocation.encryptData(cachingCmmLocation,
                    plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                    java.util.Collections.emptyMap());
            return java.util.Base64.getEncoder().encodeToString(result.getResult());
        } catch (Exception e) {
            throw new RuntimeException("KMS location encrypt failed for: " + plaintext, e);
        }
    }

    @SuppressWarnings("deprecation")
    private static void initKmsLocationIfNeeded() {
        if (awsCryptoLocation != null) return;

        String endpoint = System.getProperty("test.localstack.endpoint", "http://localhost:4566");
        String region = System.getProperty("test.aws.region", "ap-northeast-2");
        String keyAlias = "alias/cmk-1-pltelapne2"; // locationEncryptionService용 CMK

        awsCryptoLocation = com.amazonaws.encryptionsdk.AwsCrypto.builder()
            .withCommitmentPolicy(com.amazonaws.encryptionsdk.CommitmentPolicy.RequireEncryptRequireDecrypt)
            .build();

        software.amazon.awssdk.services.kms.KmsClient kmsClient =
            software.amazon.awssdk.services.kms.KmsClient.builder()
                .region(software.amazon.awssdk.regions.Region.of(region))
                .endpointOverride(java.net.URI.create(endpoint))
                .credentialsProvider(software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(
                    software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test", "test")))
                .build();

        // alias → ARN 변환
        String keyArn = kmsClient.describeKey(
            software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
                .keyId(keyAlias).build()
        ).keyMetadata().arn();

        com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider provider =
            com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider.builder()
                .defaultRegion(software.amazon.awssdk.regions.Region.of(region))
                .customRegionalClientSupplier(r -> kmsClient)
                .buildStrict(keyArn);

        com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache cache =
            new com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache(100);
        cachingCmmLocation = com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager.newBuilder()
            .withMasterKeyProvider(provider)
            .withCache(cache)
            .withMaxAge(5, java.util.concurrent.TimeUnit.MINUTES)
            .withMessageUseLimit(1000)
            .build();
    }

    /**
     * setup SQL 실행 후, 지정된 CLIENT의 ECGI를 KMS(CMK-1)로 암호화된 값으로 UPDATE한다.
     * 동시에 ECGI_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
     *
     * @param conn DB 연결
     * @param ecgiSeq 대상 ECGI_SEQ
     * @param plainEcgi 평문 ECGI (예: "1234567890")
     */
    static void encryptEcgi(Connection conn, long ecgiSeq, String plainEcgi) {
        String encrypted = kmsEncryptLocation(plainEcgi);
        String hash = hmacSha256(plainEcgi);
        try (java.sql.PreparedStatement ps = conn.prepareStatement(
                "UPDATE ECGI SET ECGI = ?, ECGI_HASH = ? WHERE ECGI_SEQ = ?")) {
            ps.setString(1, encrypted);
            ps.setString(2, hash);
            ps.setLong(3, ecgiSeq);
            int updated = ps.executeUpdate();
            if (updated == 0) {
                throw new RuntimeException("ECGI not found: ECGI_SEQ=" + ecgiSeq);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("Failed to encrypt ECGI", e);
        }
    }

    /**
     * HMAC-SHA256 해시 생성 (서버의 HashUtil.hmacSha256과 동일 로직).
     * pepper는 docker-compose.yml의 HASH_PEPPER 환경변수와 동일해야 한다.
     */
    static String hmacSha256(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) return "";
        String pepper = System.getProperty("test.hash.pepper", "test_pepper_value");
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec keySpec = new javax.crypto.spec.SecretKeySpec(
                    pepper.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(keySpec);
            byte[] hash = mac.doFinal(plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("HMAC-SHA256 failed", e);
        }
    }
}

