package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import io.restassured.http.ContentType;

/**
 * @target-controller MngTermsController (/web/super/admin/mngTerms)
 * @target-api GET /, POST /, GET /agree/{seq}, GET /agree/ajax, POST /agree
 */
class AdminMngTermsBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-mngterms-teardown.sql", AdminMngTermsBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-mngterms-setup.sql", AdminMngTermsBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "mngtermsadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-mngterms-teardown.sql", AdminMngTermsBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void beforeEach() {
        TestUtil.executeSql(dbConnection, "sql/admin-mngterms-data-setup.sql", AdminMngTermsBlackBoxTest.class);
    }

    @Test
    void NTC_getMngTerms_service() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when().get("/web/super/admin/mngTerms")
        .then().log().all().statusCode(200)
            .body("mngTermsSeq", equalTo(96001))
            .body("link", equalTo("https://example.com/service-terms"));
    }

    @Test
    void NTC_getMngTerms_privacy() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "02")
        .when().get("/web/super/admin/mngTerms")
        .then().log().all().statusCode(200)
            .body("mngTermsSeq", equalTo(96002))
            .body("link", equalTo("https://example.com/privacy-terms"));
    }

    @Test
    void NTC_createMngTerms_success() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("link", "https://example.com/new-terms")
            .formParam("termsType", "01")
        .when().post("/web/super/admin/mngTerms")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    @Test
    void VTC_createMngTerms_xssInjection() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("link", "<script>alert('xss')</script>")
            .formParam("termsType", "01")
        .when().post("/web/super/admin/mngTerms")
        .then().log().all().statusCode(200)
            .body("err", equalTo("002"))
            .body("errMsg", equalTo("VULNERABLE_VALUE"));
    }

    @Test
    void NTC_getMngAgreeTermsDetail() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/super/admin/mngTerms/agree/96001")
        .then().log().all().statusCode(200)
            .body("mngTerms.title", equalTo("약관 v1"))
            .body("mngTerms.content", equalTo("약관 내용입니다."))
            .body("mngTerms.version", equalTo(1));
    }

    @Test
    void NTC_getMngAgreeTermsList() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 10)
            .queryParam("start", 0)
        .when().get("/web/super/admin/mngTerms/agree/ajax")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("iTotalRecords", greaterThanOrEqualTo(1));
    }

    @Test
    void NTC_createMngAgreeTerms() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("title", "신규 약관 v2")
            .formParam("version", 2)
            .formParam("content", "신규 약관 내용입니다.")
        .when().post("/web/super/admin/mngTerms/agree")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/super/admin/mngTerms/agree/ajax")
        .then().log().all().statusCode(401);
    }
}

