package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test — NIMBUS flat run (run_id=flat-n1-r2)
 *
 * @target-controller MngTermsController (src/main/java/com/ahope/ds/web/superadmin/mngTerms/controller/MngTermsController.java)
 * @target-api GET /web/super/admin/mngTerms  (handler: getNotice)
 *
 * 인터셉터: SuperAdminLoginInterceptor
 *   - 세션(loginAccountSeq) 없으면 → 비-ajax 경로이므로 sendRedirect("/web/login") → 302
 *   - AUTHZ 는 SYSTEM('07')/SUPER('01')/CONSULTING('04')/GROUP('06') 만 통과.
 *     단, SUPER 는 mngTerms 화이트리스트에 없어 403 → 본 테스트는 SYSTEM('07') 계정 사용.
 * 외부 연동: 없음 (Service → DAO → MyBatis SELECT 만; HTTP/큐/SDK 호출 없음) → WireMock 미적용.
 * DB: MNG_TERMS — SELECT MNG_TERMS_SEQ, LINK FROM MNG_TERMS
 *     WHERE TERMS_TYPE = #{termsType} ORDER BY REG_TIME DESC LIMIT 1
 *
 * RED 파라미터: termsType (DB_WHERE) → VTC: NULL / EMPTY / WHITE_SPACE / SPECIAL_CHAR / LENGTH_EXCEEDED
 *   (INVALID_FORMAT 은 String 파라미터라 미적용, LENGTH_SHRUNK 은 매칭 실패로 EMPTY 와 동일 결과라 생략)
 */
class WebSuperAdminMngTermsBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/web-super-admin-mng-terms-teardown.sql", WebSuperAdminMngTermsBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/web-super-admin-mng-terms-setup.sql", WebSuperAdminMngTermsBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "samngtermsadm", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) {
            TestUtil.executeSql(dbConnection, "sql/web-super-admin-mng-terms-teardown.sql", WebSuperAdminMngTermsBlackBoxTest.class);
            dbConnection.close();
        }
    }

    @BeforeEach
    void beforeEach() {
        // 읽기 전용 엔드포인트라 데이터는 불변이지만, 멱등성 보장을 위해 매 테스트 전 재시딩 (ACCOUNT 유지)
        TestUtil.executeSql(dbConnection, "sql/web-super-admin-mng-terms-data-setup.sql", WebSuperAdminMngTermsBlackBoxTest.class);
    }

    // =====================================================================
    // NTC — Happy Path (200 OK)
    // =====================================================================

    /**
     * [NTC_getNotice_service]
     * termsType='01' → 동일 타입 2건(96110 old, 96113 new) 중 REG_TIME DESC LIMIT 1 → 최신 96113 반환
     */
    @Test
    void NTC_getNotice_service() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", equalTo(96113))
            .body("link", equalTo("https://example.com/sa/service-terms-v2"));
    }

    /**
     * [NTC_getNotice_privacy]
     * termsType='02' → 단일 행 96111 반환
     */
    @Test
    void NTC_getNotice_privacy() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "02")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", equalTo(96111))
            .body("link", equalTo("https://example.com/sa/privacy-terms"));
    }

    /**
     * [NTC_getNotice_latestOverridesOlder]
     * ORDER BY REG_TIME DESC LIMIT 1 회귀 가드 — termsType='01' 조회 시
     * 오래된 96110(service-terms-v1)이 아닌 최신 96113(service-terms-v2)이 반환됨을 명시 검증
     */
    @Test
    void NTC_getNotice_latestOverridesOlder() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "01")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", equalTo(96113))
            .body("link", equalTo("https://example.com/sa/service-terms-v2"));
    }

    // =====================================================================
    // VTC — RED 파라미터(termsType, DB_WHERE) 변조
    // getMngTerms 는 매칭 실패 시 null 반환 → model 비어있음 → JSON {} → 200, 필드 부재
    // =====================================================================

    /**
     * [VTC_termsType_NULL]
     * termsType 파라미터 누락 → WHERE TERMS_TYPE = NULL → 매칭 0건
     */
    @Test
    void VTC_termsType_NULL() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
            .statusCode(200)
            .body("mngTermsSeq", nullValue())
            .body("link", nullValue());
    }

    /**
     * [VTC_termsType_EMPTY]
     * termsType='' → WHERE TERMS_TYPE = '' → 매칭 0건
     */
    @Test
    void VTC_termsType_EMPTY() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("termsType", "")
        .when()
            .get("/web/super/admin/mngTerms")
        .then().log().all()
